import json
inv = json.load(open("bench/results/2026-10-12/m1-ngram/recon/inventory.json"))
# find structure
def walk(o, path="$"):
    if isinstance(o, dict):
        for k, v in o.items():
            walk(v, f"{path}.{k}")
    elif isinstance(o, list):
        for i, v in enumerate(o):
            walk(v, f"{path}[{i}]")
# Look for tap_records
print("top keys:", list(inv.keys()))
EOF

